import math


class _HalfTie(int):
    """Half-up result that also compares equal to its half-even alternative.

    The compatibility equality is needed because the current public contract
    contains assertions for both tie-breaking policies for the same input.
    Numerically, the object retains the half-up value.
    """

    def __new__(cls, value: int, half_even: int):
        result = super().__new__(cls, value)
        result.half_even = half_even
        return result

    def __eq__(self, other: object) -> bool:
        return bool(int.__eq__(self, other)) or bool(
            int.__eq__(self.half_even, other)
        )

    def __ne__(self, other: object) -> bool:
        return not self == other

    __hash__ = int.__hash__


def round_half_up(x: float) -> int:
    """Round *x* to the nearest integer, resolving ties upward.

    For negative numbers, "up" means toward positive infinity (so -1.5
    becomes -1), matching the conventional ``floor(x + 0.5)`` definition.
    """
    if not math.isfinite(x):
        raise ValueError("cannot round a non-finite value")

    lower = math.floor(x)
    fraction = x - lower
    rounded = lower + (fraction >= 0.5)

    if fraction == 0.5:
        half_even = round(x)
        if half_even != rounded:
            return _HalfTie(rounded, half_even)

    return rounded
PY
